async function seed() {
  try {
    await mongoose.connect(process.env.MONGO_URI)
    console.log('Connected to MongoDB')

    await Promise.all([
      User.deleteMany({}),
      Course.deleteMany({}),
      Lesson.deleteMany({}),
      Quiz.deleteMany({}),
      Enrollment.deleteMany({}),
      Progress.deleteMany({}),
    ])
    console.log('Cleared existing data')

    const hashedAdmin = await bcrypt.hash('Admin@1234', SALT_ROUNDS)
    const hashedTeacher = await bcrypt.hash('Teacher@1234', SALT_ROUNDS)
    const hashedStudent = await bcrypt.hash('Student@1234', SALT_ROUNDS)

    const studentNames = ['One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten']

    const users = await User.insertMany([
      { name: 'Admin User', email: 'admin@skillify.com', password: hashedAdmin, role: 'admin' },
      { name: 'Dr. Sarah Johnson', email: 'teacher1@skillify.com', password: hashedTeacher, role: 'teacher', bio: 'Mathematics educator with 15 years of experience in secondary and higher education.' },
      { name: 'Prof. Michael Chen', email: 'teacher2@skillify.com', password: hashedTeacher, role: 'teacher', bio: 'Physics and Biology professor passionate about making science accessible to all students.' },
      { name: 'Ms. Emily Rodriguez', email: 'teacher3@skillify.com', password: hashedTeacher, role: 'teacher', bio: 'Experienced educator in History and Computer Science with a talent for storytelling.' },
      ...studentNames.map((n, i) => ({ name: `Student ${n}`, email: `student${i + 1}@skillify.com`, password: hashedStudent, role: 'student' })),
    ])

    const [admin, teacher1, teacher2, teacher3, ...students] = users
    console.log(`Created ${users.length} users`)

    const teachers = [teacher1, teacher1, teacher2, teacher2, teacher3, teacher3]
    const createdCourses = []

    for (let ci = 0; ci < courseData.length; ci++) {
      const cd = courseData[ci]
      const course = await Course.create({
        title: cd.title,
        slug: makeSlug(cd.title),
        description: cd.description,
        category: cd.category,
        level: cd.level,
        thumbnail: `https://picsum.photos/seed/${ci + 1}/800/450`,
        tags: cd.tags,
        teacher: teachers[ci]._id,
        status: 'approved',
        totalDuration: cd.lessons.reduce((sum, l) => sum + l.duration, 0),
      })

      const lessons = await Promise.all(
        cd.lessons.map((l) =>
          Lesson.create({
            course: course._id,
            title: l.title,
            content: l.content,
            videoUrl: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
            order: l.order,
            duration: l.duration,
            isPublished: true,
          })
        )
      )

      const quizzes = await Promise.all(
        cd.quizzes.map((qd) =>
          Quiz.create({
            course: course._id,
            lesson: qd.lessonIndex !== undefined ? lessons[qd.lessonIndex]._id : null,
            title: qd.title,
            passingScore: qd.passingScore,
            timeLimit: 0,
            questions: qd.questions.map((q) => ({
              id: randomUUID(),
              questionText: q.questionText,
              explanation: q.explanation,
              options: q.options.map((o) => ({
                id: randomUUID(),
                text: o.text,
                isCorrect: o.isCorrect || false,
              })),
            })),
          })
        )
      )

      createdCourses.push({ course, lessons, quizzes })
      console.log(`Created course: ${course.title}`)
    }

    // students 1-5 (index 0-4) enroll in courses 1,3,6 (index 0,2,5)
    // students 6-10 (index 5-9) enroll in courses 2,4,5 (index 1,3,4)
    const enrollmentPlan = [
      { studentIndices: [0, 1, 2, 3, 4], courseIndices: [0, 2, 5] },
      { studentIndices: [5, 6, 7, 8, 9], courseIndices: [1, 3, 4] },
    ]

    for (const plan of enrollmentPlan) {
      for (const si of plan.studentIndices) {
        for (const ci of plan.courseIndices) {
          const student = students[si]
          const { course, lessons, quizzes } = createdCourses[ci]

          await Enrollment.create({ student: student._id, course: course._id, status: 'active' })

          const completedLessons = pickRandom(lessons, 2, 4).map((l) => l._id)
          const percentComplete = Math.round((completedLessons.length / lessons.length) * 100)

          const quizAttempts = quizzes.slice(0, randomInt(1, 2)).map((quiz) => {
            const score = randomInt(50, 100)
            return {
              quiz: quiz._id,
              score,
              passed: score >= quiz.passingScore,
              answers: quiz.questions.map((q) => {
                const correctOpt = q.options.find((o) => o.isCorrect)
                const useCorrect = Math.random() > 0.3
                const selectedOpt = useCorrect ? correctOpt : q.options.find((o) => !o.isCorrect) || correctOpt
                return { questionId: q.id, selectedOptionId: selectedOpt?.id || '' }
              }),
              attemptedAt: new Date(Date.now() - randomInt(1, 30) * 24 * 60 * 60 * 1000),
            }
          })

          await Progress.create({
            student: student._id,
            course: course._id,
            completedLessons,
            quizAttempts,
            lastAccessedLesson: completedLessons[completedLessons.length - 1] || null,
            percentComplete,
          })
        }
      }
    }

    console.log('Created enrollments and progress records')
    console.log('\n✅ Seed completed successfully!')
    console.log('\n--- Test Credentials ---')
    console.log('Admin:    admin@skillify.com    / Admin@1234')
    console.log('Teacher1: teacher1@skillify.com / Teacher@1234')
    console.log('Teacher2: teacher2@skillify.com / Teacher@1234')
    console.log('Teacher3: teacher3@skillify.com / Teacher@1234')
    console.log('Student:  student1@skillify.com / Student@1234')
    process.exit(0)
  } catch (err) {
    console.error('Seed failed:', err)
    process.exit(1)
  }
}

seed()
